package mutate

import (
	"bytes"
	"encoding/json"
	"reflect"
	"testing"
)

// The literal byte fixtures follow snapshot.go's pre-extraction field order and
// omission rules (8585bbd). They are not generated by the encoder under test.
func TestSnapshotCodecPreservesStoredBytes(t *testing.T) {
	for _, tc := range []struct {
		name     string
		snapshot Snapshot
		want     string
	}{
		{"legacy nil", Snapshot{Version: 1, File: "a<b>.py", Language: "python"}, `{
  "version": 1,
  "file": "a<b>.py",
  "language": "python",
  "tests": null,
  "units": null
}
`},
		{"empty populations", Snapshot{Version: 1, File: "a.py", Language: "python", Tests: map[string]string{}, Units: []UnitResult{}, Listed: map[string]string{}, ListedFiles: map[string]string{}, Support: map[string]string{}}, `{
  "version": 1,
  "file": "a.py",
  "language": "python",
  "tests": {},
  "units": []
}
`},
		{"ordered judgment", Snapshot{Version: 1, File: "a.py", Language: "python", Tests: map[string]string{"test_a.py": "h"}, Units: []UnitResult{{Namespace: "a", Name: "f", Hash: "h", StartLine: 2, EndLine: 3, Survived: 1, Sites: 1, Mutants: []Mutant{{Line: 3, Column: 5, Offset: 8, Original: "<", Replacement: "<=", Outcome: Survived, Scope: ScopeAllTests, Tests: []string{"id"}, SuiteEvidence: &SuiteEvidence{Tests: map[string]string{}, Support: nil}, Excepted: "never serialized"}}, Stale: true}}, Listed: map[string]string{"id": "test_a.py"}, ListedFiles: map[string]string{"test_a.py": "h"}, Support: map[string]string{"support": "s"}}, `{
  "version": 1,
  "file": "a.py",
  "language": "python",
  "tests": {
    "test_a.py": "h"
  },
  "units": [
    {
      "namespace": "a",
      "name": "f",
      "hash": "h",
      "start_line": 2,
      "end_line": 3,
      "killed": 0,
      "survived": 1,
      "uncovered": 0,
      "sites": 1,
      "mutants": [
        {
          "line": 3,
          "column": 5,
          "offset": 8,
          "original": "<",
          "replacement": "<=",
          "outcome": "survived",
          "scope": "all-tests",
          "tests": [
            "id"
          ],
          "suite_evidence": {
            "tests": {},
            "support": null
          }
        }
      ],
      "stale": true
    }
  ],
  "listed": {
    "id": "test_a.py"
  },
  "listed_files": {
    "test_a.py": "h"
  },
  "support": {
    "support": "s"
  }
}
`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var b bytes.Buffer
			enc := json.NewEncoder(&b)
			enc.SetIndent("", "  ")
			enc.SetEscapeHTML(false)
			if err := enc.Encode(SnapshotJSON(tc.snapshot)); err != nil {
				t.Fatal(err)
			}
			if b.String() != tc.want {
				t.Fatalf("stored bytes\n%s\nwant\n%s", b.String(), tc.want)
			}
			var got Snapshot
			if err := ReadSnapshotJSON(b.Bytes(), &got); err != nil {
				t.Fatal(err)
			}
			want := tc.snapshot
			if len(want.Units) > 0 {
				want.Units[0].Mutants[0].Excepted = ""
			}
			// Omitted empty optional maps read as nil, as before.
			if len(want.Listed) == 0 {
				want.Listed = nil
			}
			if len(want.ListedFiles) == 0 {
				want.ListedFiles = nil
			}
			if len(want.Support) == 0 {
				want.Support = nil
			}
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("decoded %+v, want %+v", got, want)
			}
		})
	}
}
